namespace LoupixDeck.Services.ProfileStore;

/// <summary>
/// The community profile list (<c>index.json</c> in the LoupixDeck.Profiles repository, issue #587).
/// It is generated by that repository's CI from the submitted folders. Unknown fields are ignored, so
/// a newer list keeps loading.
/// </summary>
public sealed class ProfileCatalog
{
    /// <summary>The schema this app understands. A newer list still loads; unknown fields are ignored.</summary>
    public const int SupportedSchemaVersion = 1;

    public int SchemaVersion { get; set; }

    public List<ProfileCatalogEntry> Profiles { get; set; } = [];
}

/// <summary>One shared profile, workspace or page.</summary>
public sealed class ProfileCatalogEntry
{
    /// <summary>Stable id, unique across the repository; names the entry's folder.</summary>
    public string Id { get; set; }

    public string Name { get; set; }

    public string Description { get; set; }

    /// <summary>GitHub user name of the author; names the parent folder.</summary>
    public string Author { get; set; }

    public string Version { get; set; }

    public DateTimeOffset? UpdatedAt { get; set; }

    /// <summary>SPDX id of the license the entry is shared under.</summary>
    public string License { get; set; }

    public List<string> Tags { get; set; } = [];

    /// <summary>"Windows", "Linux" and/or "macOS"; empty means every platform.</summary>
    public List<string> Platforms { get; set; } = [];

    /// <summary>What the package contains: Profile, Workspace, TouchPage or RotaryPage.</summary>
    public string Kind { get; set; }

    public ProfileCatalogDevice Device { get; set; }

    public List<ProfileCatalogPlugin> RequiredPlugins { get; set; } = [];

    /// <summary>URL of the preview image.</summary>
    public string Preview { get; set; }

    public ProfileCatalogPackage Package { get; set; }

    public string DisplayName => string.IsNullOrWhiteSpace(Name) ? Id : Name;

    /// <summary>The entry's folder on GitHub.</summary>
    public string FolderUrl =>
        $"https://github.com/{ProfileStoreService.Repository}/tree/master/profiles/{Author}/{Id}";

    /// <summary>True when the list names no platform or names the running OS.</summary>
    public bool SupportsCurrentPlatform()
    {
        if (Platforms is not { Count: > 0 })
        {
            return true;
        }

        return Platforms.Any(p => (p.Equals("Windows", StringComparison.OrdinalIgnoreCase) && OperatingSystem.IsWindows())
                                  || (p.Equals("Linux", StringComparison.OrdinalIgnoreCase) && OperatingSystem.IsLinux())
                                  || (p.Equals("macOS", StringComparison.OrdinalIgnoreCase) && OperatingSystem.IsMacOS()));
    }
}

/// <summary>The device the package was exported from.</summary>
public sealed class ProfileCatalogDevice
{
    public string Slug { get; set; }

    public string Name { get; set; }

    public int TouchButtons { get; set; }

    public int RotaryButtons { get; set; }

    public bool HasSideStrips { get; set; }
}

/// <summary>A plugin the package uses.</summary>
public sealed class ProfileCatalogPlugin
{
    public string Id { get; set; }

    public string Name { get; set; }

    public string Version { get; set; }
}

/// <summary>The <c>.loupixprofile</c> file to download.</summary>
public sealed class ProfileCatalogPackage
{
    public string FileName { get; set; }

    public string DownloadUrl { get; set; }

    public string Sha256 { get; set; }

    public long Size { get; set; }
}
